import React, { useEffect, useState } from "react";
import api from "../services/api";
import "./MLPredictionWidget.css";

const MLPredictionWidget = () => {
  const [failureRisk, setFailureRisk] = useState(null);
  const [reasons, setReasons] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const fetchPrediction = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        setError("Unauthorized: Please log in.");
        setLoading(false);
        return;
      }

      const metricsResponse = await api.get("/api/auth/metrics/", {
        headers: { Authorization: `Token ${token}` },
      });

      if (metricsResponse.data.length === 0) {
        setError("No metrics data available for prediction.");
        setLoading(false);
        return;
      }

      const latestMetrics = metricsResponse.data[0];

      const inactiveServices = [];
      const webServices = JSON.parse(latestMetrics.web_service_status || "{}");
      const dbServices = JSON.parse(latestMetrics.db_service_status || "{}");

      Object.entries(webServices).forEach(([service, status]) => {
        if (status === "inactive") inactiveServices.push(service);
      });

      Object.entries(dbServices).forEach(([service, status]) => {
        if (status === "inactive") inactiveServices.push(service);
      });

      const predictionResponse = await api.post("/api/ml/predict/", latestMetrics, {
        headers: { Authorization: `Token ${token}` },
      });

      setFailureRisk(predictionResponse.data.failure_risk);
      setReasons([
        ...predictionResponse.data.reasons,
        ...(inactiveServices.length ? [`🚨 Services Down: ${inactiveServices.join(", ")}`] : []),
      ]);
      setLoading(false);
    } catch (err) {
      console.error("Prediction API Error:", err);
      setError("Failed to fetch AI predictions.");
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPrediction();
    const interval = setInterval(fetchPrediction, 9500);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="ml-prediction-widget">
      <h3>🚨 AI Failure Prediction</h3>
      {loading ? <p>Loading...</p> : error ? <p className="error">{error}</p> : <ul>{reasons.map((r, i) => <li key={i}>{r}</li>)}</ul>}
    </div>
  );
};

export default MLPredictionWidget;
